import React, { useEffect, useRef } from 'react';
import { Code, Palette, Database, Globe, Smartphone, Layout } from 'lucide-react';

const services = [
  {
    icon: Code,
    title: 'Web Development',
    description: 'Custom web applications built with modern frameworks like React.js, ensuring high performance and scalability.',
    features: ['React.js', 'Node.js', 'RESTful APIs', 'Single Page Apps'],
    gradient: 'from-blue-500 to-cyan-500',
    color: 'blue'
  },
  {
    icon: Palette,
    title: 'UI/UX Design',
    description: 'User-centered design that combines aesthetics with functionality to create intuitive digital experiences.',
    features: ['Wireframing', 'Prototyping', 'User Research', 'Design Systems'],
    gradient: 'from-purple-500 to-pink-500',
    color: 'purple'
  },
  {
    icon: Database,
    title: 'System Development',
    description: 'Robust backend systems and database solutions using PHP and MySQL for enterprise-level applications.',
    features: ['PHP', 'MySQL', 'API Integration', 'Cloud Deployment'],
    gradient: 'from-green-500 to-teal-500',
    color: 'green'
  },
  {
    icon: Globe,
    title: 'E-Commerce Solutions',
    description: 'Complete online store development with secure payment integration and inventory management.',
    features: ['Payment Gateways', 'Product Management', 'Order Tracking', 'Analytics'],
    gradient: 'from-orange-500 to-red-500',
    color: 'orange'
  },
  {
    icon: Smartphone,
    title: 'Responsive Design',
    description: 'Mobile-first approach ensuring your website looks perfect on every device and screen size.',
    features: ['Mobile-First', 'Cross-Browser', 'Fast Loading', 'SEO Ready'],
    gradient: 'from-pink-500 to-rose-500',
    color: 'pink'
  },
  {
    icon: Layout,
    title: 'Website Maintenance',
    description: 'Ongoing support and updates to keep your website secure, fast, and up-to-date with latest technologies.',
    features: ['Security Updates', 'Performance Optimization', 'Content Updates', '24/7 Support'],
    gradient: 'from-indigo-500 to-violet-500',
    color: 'indigo'
  }
];

const Services = () => {
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  return (
    <section id="services" ref={sectionRef} className="py-24 bg-navy-900 relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute -bottom-40 -left-40 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl"></div>
      <div className="absolute top-20 right-0 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-16 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            What We Do
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Our <span className="gradient-text">Services</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We offer comprehensive web solutions tailored to meet your business needs 
            and help you succeed in the digital landscape.
          </p>
        </div>

        {/* Services Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {services.map((service, index) => (
            <div
              key={service.title}
              className="reveal group relative"
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <div className="glass-dark rounded-2xl p-8 card-hover glow-hover h-full flex flex-col">
                {/* Icon */}
                <div className={`w-16 h-16 rounded-2xl bg-gradient-to-br ${service.gradient} flex items-center justify-center mb-6 transform group-hover:scale-110 group-hover:rotate-3 transition-all duration-300 shadow-lg`}>
                  <service.icon className="w-8 h-8 text-white" />
                </div>

                {/* Content */}
                <h3 className="text-2xl font-bold text-white mb-3 group-hover:text-blue-400 transition-colors">
                  {service.title}
                </h3>
                <p className="text-gray-400 mb-6 leading-relaxed flex-grow">
                  {service.description}
                </p>

                {/* Features */}
                <div className="flex flex-wrap gap-2">
                  {service.features.map((feature) => (
                    <span
                      key={feature}
                      className={`px-3 py-1 rounded-full text-xs font-medium bg-${service.color}-500/10 text-${service.color}-400 border border-${service.color}-500/20`}
                    >
                      {feature}
                    </span>
                  ))}
                </div>

                {/* Hover gradient overlay */}
                <div className={`absolute inset-0 bg-gradient-to-br ${service.gradient} opacity-0 group-hover:opacity-5 rounded-2xl transition-opacity duration-500`}></div>
              </div>
            </div>
          ))}
        </div>

        {/* CTA */}
        <div className="text-center mt-16 reveal">
          <p className="text-gray-400 mb-6">
            Need a custom solution? Let&apos;s discuss your project requirements.
          </p>
          <a
            href="#contact"
            className="inline-flex items-center gap-2 px-8 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white font-semibold rounded-xl hover:shadow-lg hover:shadow-blue-500/25 transition-all duration-300 btn-shine"
          >
            Get a Free Consultation
          </a>
        </div>
      </div>
    </section>
  );
};

export default Services;
